import React, { useState } from 'react';
import axios from 'axios';
import './Chatbot.css'; // reuse your styling

function AIChatbot() {
  const [message, setMessage] = useState('');
  const [chat, setChat] = useState([]);

  const sendMessage = async () => {
    const res = await axios.post('http://localhost:3001/api/ai-chat', { message });
    setChat([...chat, { user: message }, { bot: res.data.reply }]);
    setMessage('');
  };

  return (
    <div className="chatbot-container">
      <h2>AI Chatbot</h2>
      <div className="chat-window">
        {chat.map((msg, i) => (
          <p key={i}><strong>{msg.user ? 'You:' : 'Bot:'}</strong> {msg.user || msg.bot}</p>
        ))}
      </div>
      <input
        value={message}
        onChange={e => setMessage(e.target.value)}
        placeholder="Type your message..."
      />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}

export default AIChatbot;
